export default {
	data() {
		return {
			isShowNavBar: false, // 是否需要导航栏

			familyAvatar: '',
			familyName: '',
			password: '',
			pwdType: 'password',
			isSubmiting: false
		};
	},
	onLoad() {
		var pages = getCurrentPages();
		this.isShowNavBar = pages.length > 1;

	},
	methods: {
		// 输入账户
		inputUsername(e) {
			this.familyName = e.target.value;
		},
		// 输入密码
		inputPwd(e) {
			this.password = e.target.value;
		},

		// 清空账户
		delUser() {
			this.familyName = '';
		},
		// 查看密码
		switchPwd() {
			this.pwdType = this.pwdType === 'text' ? 'password' : 'text';
		},
		// 注册
		registerEvt() {
			const familyName = this.familyName,
				password = this.password;

			if (!familyName.trim()) {
				this.$common.toast('请输入账号');
				return;
			}
			if (!password.trim()) {
				this.$common.toast('请输入密码');
				return;
			}

			const params = {
				familyName,
				password: password
			};
			this.isSubmiting = true;
			this.$api({
				url: '/family/register',
				data: params,
				notToken: true
			})
				.then(async res => {
					if (res) {
						this.$store.commit('SETTOKEN', res.token);
						await this.$common.setStorage('token', res.token);
						uni.redirectTo({
							url: '/pages/family/index'
						});
					}
				})
				.catch(e => {
					this.$common.toast(e.msg);
				})
				.finally(() => {
					this.isSubmiting = false;
				});
		},

		goLogin() {
			uni.navigateTo({
				url: '/pages/family/login'
			});
		}
	}
};
